defined('ABSPATH') || exit;
define('WU_HUB_VERSION','1.0.0');
define('WU_HUB_FILE',__FILE__);
final class WU_Plugin_Hub {
 const CATALOG_URL='https://raw.githubusercontent.com/jimmy-is-me/wumetax-plugin-hub/main/catalog.json';
 const CACHE_KEY='wu_hub_catalog'; const CACHE_TTL=21600;
 public function __construct(){add_action('admin_menu',[$this,'menu'],20);add_action('admin_post_wu_hub_install',[$this,'install']);add_action('wu_hub_refresh_catalog',[$this,'refresh']);add_filter('plugin_action_links_'.plugin_basename(WU_HUB_FILE),[$this,'settings_link']);}
 public static function activate(){if(!wp_next_scheduled('wu_hub_refresh_catalog'))wp_schedule_event(time()+300,'twicedaily','wu_hub_refresh_catalog');}
 public static function deactivate(){wp_clear_scheduled_hook('wu_hub_refresh_catalog');}
 public function menu(){add_menu_page('Wumetax Plugin Hub','Wumetax Hub','manage_options','wu-plugin-hub',[$this,'marketplace'],'dashicons-store',56);add_submenu_page('wu-plugin-hub','外掛市集','外掛市集','manage_options','wu-plugin-hub',[$this,'marketplace']);add_submenu_page('wu-plugin-hub','系統資訊','系統資訊','manage_options','wu-system-info',[$this,'system_info']);add_submenu_page('wu-plugin-hub','聯絡我們','聯絡我們','manage_options','wu-contact',[$this,'contact']);}
 public function settings_link($links){array_unshift($links,'<a href="'.esc_url(admin_url('admin.php?page=wu-plugin-hub')).'">外掛市集</a>');return $links;}
 public function refresh(){delete_transient(self::CACHE_KEY);$this->catalog();}
 private function catalog(){ $v=get_transient(self::CACHE_KEY);if($v!==false)return $v;$r=wp_remote_get(self::CATALOG_URL,['timeout'=>10,'headers'=>['Accept'=>'application/json']]);$v=!is_wp_error($r)?json_decode(wp_remote_retrieve_body($r),true):['plugins'=>[]];if(!is_array($v))$v=['plugins'=>[]];set_transient(self::CACHE_KEY,$v,self::CACHE_TTL);return $v;}
 private function local_plugin($file){if(!function_exists('get_plugins'))require_once ABSPATH.'wp-admin/includes/plugin.php';foreach(get_plugins() as $key=>$data)if(basename($key)===basename($file))return ['file'=>$key,'data'=>$data,'active'=>is_plugin_active($key)];return false;}
 private function action_url($slug){return wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&slug='.rawurlencode($slug)),'wu_hub_install');}
 public function install(){if(!current_user_can('install_plugins'))wp_die('權限不足');check_admin_referer('wu_hub_install');$slug=sanitize_key($_GET['slug']??'');$mode=sanitize_key($_GET['mode']??'install');$file=sanitize_text_field($_GET['file']??'');require_once ABSPATH.'wp-admin/includes/plugin.php';if($mode==='enable'&&$file)activate_plugin($file);if($mode==='disable'&&$file)deactivate_plugins($file);if($mode==='delete'&&$file){require_once ABSPATH.'wp-admin/includes/file.php';delete_plugins([$file]);}if($slug==='refresh'){delete_transient(self::CACHE_KEY);$this->catalog();}foreach(($this->catalog()['plugins']??[]) as $p){if(($p['slug']??'')!==$slug||$mode!=='update'&&$mode!=='install')continue;$package=esc_url_raw($p['package_url']??'');require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/class-wp-upgrader.php';$up=new Plugin_Upgrader(new Automatic_Upgrader_Skin());$local=$this->local_plugin($p['plugin_file']??'');if($local&&$mode==='update'){$t=get_site_transient('update_plugins');if(!is_object($t))$t=new stdClass();$t->response[$local['file']]=(object)['plugin'=>$local['file'],'slug'=>$slug,'new_version'=>$p['version'],'package'=>$package];set_site_transient('update_plugins',$t);$up->upgrade($local['file']);}elseif(!$local)$up->install($package);}wp_safe_redirect(admin_url('admin.php?page=wu-plugin-hub'));exit;}
 public function marketplace(){if(!current_user_can('manage_options'))wp_die('權限不足');$catalog=$this->catalog();?><div class="wrap wu-wrap"><header class="wu-hero"><div><h1>▰ Wumetax 外掛市集</h1><p>由 <a href="https://wumetax.com/" target="_blank" rel="noopener">Wumetax LTD</a> 開發與維護</p></div><div><span class="wu-online">● 已連線</span><a class="wu-online wu-refresh" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&slug=refresh'),'wu_hub_install')); ?>">⟳ 檢查更新</a></div></header> <div class="wu-tools"><button data-f="all">全部</button><input id="wu-search" placeholder="⌕ 搜尋外掛…"></div><section class="wu-grid"><?php foreach(($catalog['plugins']??[]) as $p):$local=$this->local_plugin($p['plugin_file']??'');?><article class="wu-card"><div class="wu-icon"><?php echo esc_html($p['icon']??'🔌'); ?></div><h2><?php echo esc_html($p['name']??'Wumetax Plugin'); ?></h2><span><?php echo esc_html($p['category']??'WordPress'); ?></span><small>v<?php echo esc_html($p['version']??'—'); ?></small><p><?php echo esc_html($p['description']??''); ?></p><footer><?php if($local&&$local['active']):?><a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&mode=disable&file='.rawurlencode($local['file'])),'wu_hub_install')); ?>">停用</a> <a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&mode=delete&file='.rawurlencode($local['file'])),'wu_hub_install')); ?>">解除安裝</a> <a class="button button-primary" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&slug='.$p['slug'].'&mode=update'),'wu_hub_install')); ?>">更新</a><?php elseif($local):?><a class="button button-primary" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&mode=enable&file='.rawurlencode($local['file'])),'wu_hub_install')); ?>">啟用</a><?php else:?><a class="button button-primary" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=wu_hub_install&slug='.$p['slug'].'&mode=install'),'wu_hub_install')); ?>">安裝</a><?php endif;?></footer></article><?php endforeach;if(empty($catalog['plugins'])): ?><article class="wu-empty"><h2>即將提供更多功能外掛</h2><p>未來只要在 catalog.json 加入外掛資料與 GitHub Release ZIP，這裡就會自動顯示並可一鍵安裝。</p></article><?php endif;?></section></div><style>.wu-wrap{max-width:1400px}.wu-hero{display:flex;justify-content:space-between;align-items:center;background:#E2F8EA;border-radius:14px;padding:28px 38px;color:#173c2b}.wu-hero a{color:#173c2b}.wu-hero h1{color:#173c2b;margin:0}.wu-hero p{margin:7px 0 0}.wu-online{background:#fff;color:#4b9975;border-radius:22px;padding:10px 15px;margin-right:10px;text-decoration:none}.wu-refresh{border:0;font-size:14px;cursor:pointer}.wu-tools{margin:24px 0;display:flex}.wu-tools button,.wu-tools input{border:1px solid #dce4e9;border-radius:22px;background:#fff;padding:10px 18px}.wu-tools input{margin-left:auto;width:260px}.wu-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}@media(max-width:1100px){.wu-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.wu-grid{grid-template-columns:1fr}}.wu-card,.wu-empty{position:relative;min-height:230px;background:#fff;border:1px solid #e0e7eb;border-radius:10px;padding:24px}.wu-icon{font-size:32px;float:left;margin-right:14px}.wu-card h2{font-size:18px;margin:8px 0 16px}.wu-card span{background:#edf3f6;border-radius:14px;padding:5px 9px;color:#668399}.wu-card small{margin-left:8px;color:#778}.wu-card p{clear:both;color:#65778a;line-height:1.7}.wu-card footer{position:absolute;right:22px;bottom:20px}.wu-card footer b{color:#4b9975}</style><script>document.getElementById('wu-search').oninput=function(){let q=this.value.toLowerCase();document.querySelectorAll('.wu-card').forEach(c=>c.style.display=c.innerText.toLowerCase().includes(q)?'block':'none)}</script><?php }
 public function system_info(){global $wpdb;$ip=wp_remote_retrieve_body(wp_remote_get('https://api.ipify.org',['timeout'=>3]));$rows=['主機傳出 IP'=>$ip?:'無法偵測','PHP'=>PHP_VERSION,'PHP 記憶體上限'=>ini_get('memory_limit'),'上傳上限'=>ini_get('upload_max_filesize'),'最大執行時間'=>ini_get('max_execution_time').'s','SSL'=>is_ssl()?'是':'否','偵錯模式'=>defined('WP_DEBUG')&&WP_DEBUG?'開啟':'關閉','時區'=>wp_timezone_string(),'Web Server'=>$_SERVER['SERVER_SOFTWARE']??'未知'];echo '<div class="wrap"><h1>系統資訊</h1><table class="widefat striped">';foreach($rows as $k=>$v)echo '<tr><th>'.esc_html($k).'</th><td>'.esc_html($v).'</td></tr>';echo '</table></div>';}
 public function contact(){echo '<div class="wrap"><h1>聯絡 Wumetax LTD</h1><p><a class="button button-primary" target="_blank" rel="noopener" href="https://wumetax.com/contact-us/">前往聯絡我們</a></p></div>';}
}
register_activation_hook(WU_HUB_FILE,['WU_Plugin_Hub','activate']);register_deactivation_hook(WU_HUB_FILE,['WU_Plugin_Hub','deactivate']);new WU_Plugin_Hub();